-- Add the irreversible global routing index for short Computer setup codes.
CREATE TABLE `computer_setup_codes` (`id` varchar(64) NOT NULL, `code_hash` char(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL, `server_id` varchar(64) NOT NULL, `computer_id` varchar(64) NOT NULL, `generation` bigint NOT NULL, `expires_at` datetime(3) NOT NULL, `created_at` datetime(3) NOT NULL, PRIMARY KEY (`code_hash`, `id`), UNIQUE INDEX `computersetupcode_code_hash` (`code_hash`), INDEX `computersetupcode_code_hash_expires_at_id` (`code_hash`, `expires_at`, `id`)) CHARSET utf8mb4 COLLATE utf8mb4_bin shardkey=`code_hash`;
